using System;
using System.Collections.Generic;
using System.IO;
using UnityEngine;

/// <summary>
/// Maps AnimTween sequence ids to shipped Resources clip take names (after .ao_).
/// Rows are generated by scripts/interlude-anim-whitelist.py — not guessed at runtime.
/// </summary>
public static class InterludeAnimResourceTakeTable
{
    const string RelativePath = "Data/Meta/InterludeAnimResourceTake.tsv";

    static readonly Dictionary<string, string> ByMeshSequence =
        new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

    static bool _loaded;

    public static void EnsureLoaded()
    {
        if (_loaded)
            return;
        _loaded = true;
        ByMeshSequence.Clear();

        string path = Path.Combine(Application.streamingAssetsPath, RelativePath);
        if (!File.Exists(path))
            return;

        using var reader = new StreamReader(path);
        string line;
        while ((line = reader.ReadLine()) != null)
        {
            if (string.IsNullOrWhiteSpace(line) || line.StartsWith("#", StringComparison.Ordinal))
                continue;
            string[] cols = line.Split('\t');
            if (cols.Length < 3)
                continue;
            string mesh = cols[0].Trim();
            string animTween = cols[1].Trim();
            string resourcesTake = cols[2].Trim();
            if (mesh.Length == 0 || animTween.Length == 0 || resourcesTake.Length == 0)
                continue;
            ByMeshSequence[mesh + "\0" + animTween] = resourcesTake;
        }
    }

    public static string ResourcesTakeName(string meshAnim, string animTweenSequence)
    {
        EnsureLoaded();
        if (string.IsNullOrEmpty(meshAnim) || string.IsNullOrEmpty(animTweenSequence))
            return animTweenSequence;
        if (ByMeshSequence.TryGetValue(meshAnim + "\0" + animTweenSequence, out string take))
            return take;
        return animTweenSequence;
    }
}